 "content": "def transform(grid):
    """Recolor monochromatic full-width/full-height non-background lines to 2."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(h):
        if grid[r][0] != background and all(v == grid[r][0] for v in grid[r]):
            out[r] = [2 if v == grid[r][0] else v for v in out[r]]
    for c in range(w):
        color = grid[0][c]
        if color != background and all(grid[r][c] == color for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    return out
